"use strict";(globalThis.webpackChunkmy_website||=[]).push([[38426],{94121(e){e.exports=JSON.parse('{"slug":"bribery-attack","title":"Bribery Attack","short":"An external attacker pays validators to deviate from the protocol, for example by signing conflicting blocks or handing over dormant keys.","category":"consensus","aliases":[],"mentalModel":null,"related":["proof-of-stake-attacks","proof-of-stake","posterior-corruption","kes"],"sources":[],"link":"/research","level":"advanced","body":"An attacker pays current or former validators to misbehave: sign double blocks, censor transactions, hand over keys, vote on a controversial proposal. Bribery is the economic version of corruption attacks, and works wherever stakeholders have keys with residual value.\\n\\nCardano mitigates bribery in two directions. Present-time bribery requires corrupting a stake majority, which under Ouroboros\'s honest-majority assumption is economically prohibitive. Past-time bribery (buying old keys) is neutralised by key-evolving signatures, which retire old keys so they cannot be sold for malicious replay."}')}}]);